#include "cpm_buffer.h"
#include <ctype.h>
#include <stdlib.h>
#include <string.h>

uint16_t CpmEndian_ReadU16LE(const void*d){const unsigned char*p=d;return(uint16_t)((uint16_t)p[0]|((uint16_t)p[1]<<8));}
uint16_t CpmEndian_ReadU16BE(const void*d){const unsigned char*p=d;return(uint16_t)(((uint16_t)p[0]<<8)|(uint16_t)p[1]);}
uint32_t CpmEndian_ReadU32LE(const void*d){const unsigned char*p=d;return(uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}
uint32_t CpmEndian_ReadU32BE(const void*d){const unsigned char*p=d;return((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|(uint32_t)p[3];}
uint64_t CpmEndian_ReadU64LE(const void*d){const unsigned char*p=d;return(uint64_t)p[0]|((uint64_t)p[1]<<8)|((uint64_t)p[2]<<16)|((uint64_t)p[3]<<24)|((uint64_t)p[4]<<32)|((uint64_t)p[5]<<40)|((uint64_t)p[6]<<48)|((uint64_t)p[7]<<56);}
uint64_t CpmEndian_ReadU64BE(const void*d){const unsigned char*p=d;return((uint64_t)p[0]<<56)|((uint64_t)p[1]<<48)|((uint64_t)p[2]<<40)|((uint64_t)p[3]<<32)|((uint64_t)p[4]<<24)|((uint64_t)p[5]<<16)|((uint64_t)p[6]<<8)|(uint64_t)p[7];}
void CpmEndian_WriteU16LE(void*d,uint16_t v){unsigned char*p=d;p[0]=(unsigned char)v;p[1]=(unsigned char)(v>>8);}void CpmEndian_WriteU16BE(void*d,uint16_t v){unsigned char*p=d;p[0]=(unsigned char)(v>>8);p[1]=(unsigned char)v;}
void CpmEndian_WriteU32LE(void*d,uint32_t v){unsigned char*p=d;p[0]=(unsigned char)v;p[1]=(unsigned char)(v>>8);p[2]=(unsigned char)(v>>16);p[3]=(unsigned char)(v>>24);}void CpmEndian_WriteU32BE(void*d,uint32_t v){unsigned char*p=d;p[0]=(unsigned char)(v>>24);p[1]=(unsigned char)(v>>16);p[2]=(unsigned char)(v>>8);p[3]=(unsigned char)v;}
void CpmEndian_WriteU64LE(void*d,uint64_t v){unsigned char*p=d;int i;for(i=0;i<8;i++)p[i]=(unsigned char)(v>>(8*i));}void CpmEndian_WriteU64BE(void*d,uint64_t v){unsigned char*p=d;int i;for(i=0;i<8;i++)p[i]=(unsigned char)(v>>(8*(7-i)));}
void CpmByteBuffer_Init(CpmByteBuffer*b){if(b){b->data=NULL;b->size=0;b->capacity=0;}}void CpmByteBuffer_Free(CpmByteBuffer*b){if(b){free(b->data);CpmByteBuffer_Init(b);}}void CpmByteBuffer_Clear(CpmByteBuffer*b){if(b)b->size=0;}
int CpmByteBuffer_Reserve(CpmByteBuffer*b,size_t c){unsigned char*p;size_t n;if(!b)return-1;if(c<=b->capacity)return 0;n=b->capacity?b->capacity:64;while(n<c){if(n>(size_t)-1/2){n=c;break;}n*=2;}p=(unsigned char*)realloc(b->data,n);if(!p)return-2;b->data=p;b->capacity=n;return 0;}
int CpmByteBuffer_Append(CpmByteBuffer*b,const void*d,size_t s){if(!b||(!d&&s))return-1;if(s>(size_t)-1-b->size)return-2;if(CpmByteBuffer_Reserve(b,b->size+s)!=0)return-2;if(s)memcpy(b->data+b->size,d,s);b->size+=s;return 0;}
int CpmByteBuffer_AppendU8(CpmByteBuffer*b,uint8_t v){return CpmByteBuffer_Append(b,&v,1);}int CpmByteBuffer_AppendU16LE(CpmByteBuffer*b,uint16_t v){unsigned char x[2];CpmEndian_WriteU16LE(x,v);return CpmByteBuffer_Append(b,x,2);}int CpmByteBuffer_AppendU16BE(CpmByteBuffer*b,uint16_t v){unsigned char x[2];CpmEndian_WriteU16BE(x,v);return CpmByteBuffer_Append(b,x,2);}int CpmByteBuffer_AppendU32LE(CpmByteBuffer*b,uint32_t v){unsigned char x[4];CpmEndian_WriteU32LE(x,v);return CpmByteBuffer_Append(b,x,4);}int CpmByteBuffer_AppendU32BE(CpmByteBuffer*b,uint32_t v){unsigned char x[4];CpmEndian_WriteU32BE(x,v);return CpmByteBuffer_Append(b,x,4);}
void CpmByteReader_Init(CpmByteReader*r,const void*d,size_t s){if(r){r->data=(const unsigned char*)d;r->size=s;r->offset=0;}}size_t CpmByteReader_Remaining(const CpmByteReader*r){return r&&r->offset<=r->size?r->size-r->offset:0;}
int CpmByteReader_Read(CpmByteReader*r,void*out,size_t s){if(!r||(!out&&s)||CpmByteReader_Remaining(r)<s)return-1;if(s)memcpy(out,r->data+r->offset,s);r->offset+=s;return 0;}int CpmByteReader_ReadU8(CpmByteReader*r,uint8_t*v){return CpmByteReader_Read(r,v,1);}int CpmByteReader_ReadU16LE(CpmByteReader*r,uint16_t*v){unsigned char x[2];if(!v||CpmByteReader_Read(r,x,2))return-1;*v=CpmEndian_ReadU16LE(x);return 0;}int CpmByteReader_ReadU16BE(CpmByteReader*r,uint16_t*v){unsigned char x[2];if(!v||CpmByteReader_Read(r,x,2))return-1;*v=CpmEndian_ReadU16BE(x);return 0;}int CpmByteReader_ReadU32LE(CpmByteReader*r,uint32_t*v){unsigned char x[4];if(!v||CpmByteReader_Read(r,x,4))return-1;*v=CpmEndian_ReadU32LE(x);return 0;}int CpmByteReader_ReadU32BE(CpmByteReader*r,uint32_t*v){unsigned char x[4];if(!v||CpmByteReader_Read(r,x,4))return-1;*v=CpmEndian_ReadU32BE(x);return 0;}
int CpmHex_Encode(const void*d,size_t s,char*out,size_t cap,int upper,char sep){const unsigned char*p=d;const char*hex=upper?"0123456789ABCDEF":"0123456789abcdef";size_t i,u=0,need=s?2*s+(sep?s-1:0)+1:1;if(!out||cap<need||(!d&&s))return-1;for(i=0;i<s;i++){if(i&&sep)out[u++]=sep;out[u++]=hex[p[i]>>4];out[u++]=hex[p[i]&15];}out[u]='\0';return 0;}
static int hv(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return-1;}
int CpmHex_Decode(const char*t,unsigned char*out,size_t cap,size_t*outSize){int high=-1;size_t n=0;if(!t||(!out&&cap))return-1;while(*t){int v=hv(*t++);if(v<0){if(isspace((unsigned char)t[-1])||t[-1]==':'||t[-1]=='-'||t[-1]==',')continue;return-2;}if(high<0)high=v;else{if(n>=cap)return-3;out[n++]=(unsigned char)((high<<4)|v);high=-1;}}if(high>=0)return-2;if(outSize)*outSize=n;return 0;}
